       };

+      // -----------------------------------------------------------------
+      // 3️⃣ Attach the Environment block if needed
+      // -----------------------------------------------------------------
+      if (hasEnv) {
+        functionObject.Properties.Environment = {
+          Variables: mergedEnv,
+        };
