-        err.code = code;
-        reject(err);
-      }
-    });
+    child.on('close', code => {
+      if (code === 0) {
+        resolve({ stdout, stderr });
+      } else {
+        const err = new Error(`Command failed with exit code ${code}`);
+        // @ts-ignore
+        err.code = code;
